75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    /**
84	     * Source of the {@link OwnerCreatedEvent}'s {@code seq}: a process-wide, monotonically increasing counter across
85	     * every owner create, so the structured audit events carry a strictly ordered sequence regardless of which
86	     * controller instance handled the request.
87	     */
88	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
89	
90	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
91	    private static final int MAX_OWNERS_PER_CITY = 50;
92	
93	    /** Once a city already holds at least this many owners (but is not yet full), a further create there is flagged with a capacity warning. */
94	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
95	
96	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
97	    private static final int MAX_OWNERS_PER_DAY = 100;
98	
99	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
100	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
101	
102	    /** Request header carrying the client-supplied idempotency key for a create; see {@link #addOwner}. */
103	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
104	
105	    /**
106	     * Remembers, per idempotency key, the id of the owner the first create with that key produced, so a repeated
107	     * create with an already-seen key returns the original owner instead of creating a duplicate.
108	     */
109	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
110	
111	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
112	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
113	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
114	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
115	
116	    private final ClinicService clinicService;
117	
118	    private final OwnerMapper ownerMapper;
119	
120	    private final PetMapper petMapper;
121	
122	    private final VisitMapper visitMapper;
123	
124	    private final TelephoneNormalizer telephoneNormalizer;
125	
126	    private final AddressNormalizer addressNormalizer;
127	
128	    private final EmailNormalizer emailNormalizer;
129	
130	    private final IdentityKeyResolver identityKeyResolver;
131	
132	    private final HouseholdResolver householdResolver;
133	
134	    /** The current request, used to read the optional {@code Idempotency-Key} header on a create. */
135	    private final HttpServletRequest request;
136	
137	    public OwnerRestControllerV1(ClinicService clinicService,
138	                                 OwnerMapper ownerMapper,
139	                                 PetMapper petMapper,
140	                                 VisitMapper visitMapper,
141	                                 TelephoneNormalizer telephoneNormalizer,
142	                                 AddressNormalizer addressNormalizer,
143	                                 EmailNormalizer emailNormalizer,
144	                                 IdentityKeyResolver identityKeyResolver,
145	                                 HouseholdResolver householdResolver,
146	                                 HttpServletRequest request) {
147	        this.clinicService = clinicService;
148	        this.ownerMapper = ownerMapper;
149	        this.petMapper = petMapper;
150	        this.visitMapper = visitMapper;
151	        this.telephoneNormalizer = telephoneNormalizer;
152	        this.addressNormalizer = addressNormalizer;
153	        this.emailNormalizer = emailNormalizer;
154	        this.identityKeyResolver = identityKeyResolver;
155	        this.householdResolver = householdResolver;
156	        this.request = request;
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
162	        Collection<Owner> owners;
163	        if (lastName != null) {
164	            owners = this.clinicService.findOwnerByLastName(lastName);
165	        } else {
166	            owners = this.clinicService.findAllOwners();
167	        }
168	        if (owners.isEmpty()) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        owners.forEach(this::populateHouseholdMemberCount);
172	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
173	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        populateHouseholdMemberCount(owner);
184	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
185	    }
186	
187	    /**
188	     * Maps an owner to its DTO and stamps on the two derived values the mapper cannot produce on its own, each because
189	     * it depends on more than the single owner: the {@code identityKey} (see
190	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner, and the household-capped
191	     * {@code membershipLevel} (see {@link #cappedMembershipLevel}), which the mapper derives from the owner alone but
192	     * which the ceiling rule then caps against the owner's fellow household members. The capped level replaces the
193	     * mapper's uncapped one on the returned DTO.
194	     *
195	     * @param owner the owner to map
196	     * @return the owner DTO carrying its identity key and household-capped membership level
197	     */
198	    private OwnerDto toOwnerDto(Owner owner) {
199	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
200	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
201	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
202	        return ownerDto;
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Transactional
207	    @Override
208	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
209	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
210	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
211	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
212	            if (replay != null) {
213	                return replay;
214	            }
215	        }
216	        Owner owner = createOwner(ownerFieldsDto);
217	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
218	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
219	        }
220	        return createdOwnerResponse(owner);
221	    }
222	
223	    /**
224	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
225	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
226	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
227	     * normally.
228	     *
229	     * @param idempotencyKey the client-supplied idempotency key from the request header
230	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
231	     */
232	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
233	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
234	        if (existingId == null) {
235	            return null;
236	        }
237	        Owner owner = this.clinicService.findOwnerById(existingId);
238	        if (owner == null) {
239	            return null;
240	        }
241	        populateHouseholdMemberCount(owner);
242	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
243	    }
244	
245	    /**
246	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
247	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
248	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guard then runs against those derived
249	     * fields (see {@link #requireUniqueIdentity}) before the soft-duplicate
250	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
251	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
252	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
253	     *
254	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
255	     * @return the newly created, persisted owner
256	     */
257	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
258	        normalizeAndValidate(ownerFieldsDto);
259	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
260	        populateDerivedFields(owner, ownerFieldsDto);
261	        requireUniqueIdentity(owner);
262	        flagPossibleDuplicate(owner, ownerFieldsDto);
263	        this.clinicService.saveOwner(owner);
264	        populateHouseholdMemberCount(owner);
265	        auditOwnerCreated(owner);
266	        return owner;
267	    }
268	
269	    /**
270	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
271	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
272	     * canonical URL.
273	     *
274	     * @param owner the newly created, persisted owner
275	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
276	     */
277	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
278	        OwnerDto ownerDto = toOwnerDto(owner);
279	        HttpHeaders headers = new HttpHeaders();
280	        headers.setLocation(UriComponentsBuilder.newInstance()
281	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
282	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
283	    }
284	
285	    /**
286	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
287	     * its id, member id and registration date alongside the membership level (see
288	     * {@link MembershipLevelResolver#deriveMembershipLevel}) derived purely for the audit trail.
289	     *
290	     * <p>In addition to the human-readable line, a single immutable structured event is emitted as JSON (see
291	     * {@link OwnerCreatedEvent}), carrying a monotonically increasing {@code seq} (see
292	     * {@link #OWNER_CREATED_SEQUENCE}), the owner's id, its primary identifier (see
293	     * {@link #primaryIdentifier(Owner)}) and its membership level under the {@code OWNER_CREATED} event type.
294	     *
295	     * @param owner the newly created, persisted owner, with all its derived fields already in place
296	     */
297	    private void auditOwnerCreated(Owner owner) {
298	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
299	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
300	            MembershipLevelResolver.deriveMembershipLevel(owner));
301	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
302	            owner.getId(), primaryIdentifier(owner), cappedMembershipLevel(owner));
303	        AUDIT.info(event.toJson());
304	    }
305	
306	    /**
307	     * Returns the owner's primary identifier — the unified {@code memberId} the structured {@link OwnerCreatedEvent}
308	     * carries as the owner's identity.
309	     *
310	     * @param owner the newly created, persisted owner
311	     * @return the owner's member id
312	     */
313	    private String primaryIdentifier(Owner owner) {
314	        return owner.getMemberId();
315	    }
316	
317	    /**
318	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
319	     * already exist, in the order each field depends on. The {@code memberId} is derived from the owner's own
320	     * fields (see {@link IdentityKeyResolver#deriveMemberId}); the {@code namesakeCount} (see
321	     * {@link #countNamesakes}), {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) and
322	     * {@code capacityWarning} (see {@link #computeCapacityWarning}) are snapshots of the existing owners taken before
323	     * this owner is saved, so none counts the new owner itself; and the shared
324	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
325	     * last name and postcode, so it is in place before the owner's household membership level is capped (see
326	     * {@link #cappedMembershipLevel}). The owner is mutated in place; the caller applies the duplicate guards and saves it.
327	     *
328	     * @param owner          the newly mapped owner about to be saved
329	     * @param ownerFieldsDto the incoming owner payload
330	     */
331	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
332	        owner.setMemberId(deriveUniqueMemberId(owner));
333	        owner.setNamesakeCount(countNamesakes(owner));
334	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
335	        owner.setCapacityWarning(computeCapacityWarning(owner.getCity()));
336	        assignHouseholdId(owner);
337	    }
