339	    /**
340	     * Derives an owner's {@code memberId} and de-duplicates it against the owners that already exist. The base id
341	     * is the pure derivation (see {@link IdentityKeyResolver#deriveMemberId}); when it collides with an existing
342	     * owner's {@code memberId} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
343	     * makes the whole id unique. Evaluated before the new owner is saved, so the collision check reflects only owners
344	     * that predate this create; distinct owners therefore always receive distinct member ids.
345	     *
346	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
347	     * @return the de-duplicated member id, unique across all existing owners
348	     */
349	    private String deriveUniqueMemberId(Owner owner) {
350	        String base = identityKeyResolver.deriveMemberId(owner);
351	        Collection<Owner> existing = this.clinicService.findAllOwners();
352	        String candidate = base;
353	        int n = 2;
354	        while (isMemberIdInUse(candidate, existing)) {
355	            candidate = base + "-" + n;
356	            n++;
357	        }
358	        return candidate;
359	    }
360	
361	    private boolean isMemberIdInUse(String memberId, Collection<Owner> existing) {
362	        return existing.stream().anyMatch(other -> memberId.equals(other.getMemberId()));
363	    }
