365	    /**
366	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
367	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
368	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
369	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
370	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
371	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
372	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
373	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
374	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
375	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
376	     * assigned (see {@link #requireUniqueIdentity}).
377	     *
378	     * @param ownerFieldsDto the incoming owner payload, mutated in place
379	     * @throws MissingOwnerFieldsException if any required field is missing or blank
380	     */
381	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
382	        normalizeAddress(ownerFieldsDto);
383	        validateRequiredFields(ownerFieldsDto);
384	        validatePostcode(ownerFieldsDto);
385	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
386	        ownerFieldsDto.setTelephone(telephone);
387	        requireCityHasCapacity(ownerFieldsDto.getCity());
388	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
389	        ownerFieldsDto.setRegistrationDate(registrationDate);
390	        requireDailyLimitNotReached(registrationDate);
391	        normalizeEmail(ownerFieldsDto);
392	    }
