394	    /**
395	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
396	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
397	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
398	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
399	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
400	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
401	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
402	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
403	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
404	     *
405	     * @param ownerFieldsDto the incoming owner payload, mutated in place
406	     */
407	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
408	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
409	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
410	        if (!line1.isEmpty()) {
411	            ownerFieldsDto.setAddressLine1(line1);
412	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
413	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
414	        }
415	        else {
416	            ownerFieldsDto.setAddressLine1(null);
417	            ownerFieldsDto.setAddressLine2(null);
418	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
419	        }
420	    }
421	
422	    /**
423	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
424	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
425	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
426	     * place so the caller can map and save it directly.
427	     *
428	     * @param ownerFieldsDto the incoming owner payload, mutated in place
429	     */
430	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
431	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
432	    }
