434	    /**
435	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
436	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
437	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
438	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
439	     * date is rejected.
440	     *
441	     * @param ownerFieldsDto the incoming owner payload
442	     * @return the effective registration date rolled forward onto a business day
443	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
444	     */
445	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
446	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
447	        if (effective == null) {
448	            effective = LocalDate.now();
449	        }
450	        else if (effective.isAfter(LocalDate.now())) {
451	            throw new FutureRegistrationDateException(
452	                "the registration date must not be later than the current server date");
453	        }
454	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
455	            || PUBLIC_HOLIDAYS.contains(effective)) {
456	            effective = effective.plusDays(1);
457	        }
458	        return effective;
459	    }
