461	    /**
462	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
463	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
464	     * further owner may be created for that day.
465	     *
466	     * @param registrationDate the adjusted business-day registration date of the owner being created
467	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
468	     */
469	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
470	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
471	            throw new DailyOwnerLimitExceededException(
472	                "the maximum number of owners for today has already been reached");
473	        }
474	    }
