476	    /**
477	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
478	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
479	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
480	     * warning threshold) so both express the same per-day count in one place.
481	     *
482	     * @param registrationDate the adjusted business-day registration date to count owners for
483	     * @return the number of existing owners registered on that day
484	     */
485	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
486	        return this.clinicService.findAllOwners().stream()
487	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
488	            .count();
489	    }
