491	    /**
492	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
493	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
494	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
495	     * reflects only owners that predate it.
496	     *
497	     * @param registrationDate the adjusted business-day registration date of the owner being created
498	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
499	     */
500	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
501	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
502	    }
