504	    /**
505	     * Counts how many existing owners already share the given owner's first and last name, compared
506	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
507	     * create; it is zero when the owner's name is unique.
508	     *
509	     * @param owner the newly mapped owner about to be saved
510	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
511	     */
512	    private int countNamesakes(Owner owner) {
513	        String firstName = owner.getFirstName();
514	        String lastName = owner.getLastName();
515	        return (int) this.clinicService.findAllOwners().stream()
516	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
517	                && lastName.equalsIgnoreCase(existing.getLastName()))
518	            .count();
519	    }
