521	    /**
522	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
523	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
524	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
525	     *
526	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
527	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
528	     * flat {@code address}.
529	     *
530	     * @param ownerFieldsDto the owner payload to validate
531	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
532	     */
533	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
534	        List<String> missingFields = new ArrayList<>();
535	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
536	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
537	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
538	        requireText(missingFields, "city", ownerFieldsDto.getCity());
539	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
540	        if (!missingFields.isEmpty()) {
541	            throw new MissingOwnerFieldsException(missingFields);
542	        }
543	    }
544	
545	    private void requireText(List<String> missingFields, String fieldName, String value) {
546	        if (value == null || value.isBlank()) {
547	            missingFields.add(fieldName);
548	        }
549	    }
