551	    /**
552	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
553	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
554	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
555	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
556	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
557	     *
558	     * @param ownerFieldsDto the incoming owner payload
559	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
560	     */
561	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
562	        String postcode = ownerFieldsDto.getPostcode();
563	        if (postcode == null) {
564	            return;
565	        }
566	        Region region = Region.forCity(ownerFieldsDto.getCity());
567	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
568	            throw new InvalidPostcodeException(
569	                "postcode " + postcode + " is not valid for the city's region " + region.name());
570	        }
571	    }
