573	    /**
574	     * Rejects creating an owner whose whole derived {@code identityKey} (see
575	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
576	     * duplicate only when its normalized telephone, email and last-name Soundex all match another owner's. This single
577	     * identity key is now the sole duplicate rule: because the telephone is part of the key, owners that share only
578	     * their last name and postcode but carry different telephones have distinct keys and are not caught here — they are
579	     * created and flagged as a soft match instead (see {@link #flagPossibleDuplicate}), their membership level being
580	     * capped where they join an existing household (see {@link #cappedMembershipLevel}). Owners that have been
581	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted owner
582	     * does not block the create.
583	     *
584	     * @param owner the newly mapped owner about to be saved, with its normalized fields already in place
585	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
586	     */
587	    private void requireUniqueIdentity(Owner owner) {
588	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
589	        boolean inUse = this.clinicService.findAllOwners().stream()
590	            .filter(existing -> !existing.isDeleted())
591	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
592	        if (inUse) {
593	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
594	        }
595	    }
