597	    /**
598	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
599	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. A declared
600	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
601	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
602	     * duplicate when some existing owner shares its last-name Soundex (see {@link SoundexResolver#soundex}) and its
603	     * postcode but has a different {@code identityKey}. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
604	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
605	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
606	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
607	     *
608	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
609	     * @param ownerFieldsDto the incoming owner payload
610	     */
611	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
612	        owner.setPossibleDuplicate(false);
613	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
614	            return;
615	        }
616	        String postcode = owner.getPostcode();
617	        if (postcode == null || postcode.isBlank()) {
618	            return;
619	        }
620	        for (Owner existing : this.clinicService.findAllOwners()) {
621	            if (isPossibleDuplicateOf(owner, existing)) {
622	                owner.setPossibleDuplicate(true);
623	                owner.setPossibleDuplicateOf(existing.getId());
624	                return;
625	            }
626	        }
627	    }
628	
629	    /**
630	     * Decides whether {@code existing} makes {@code owner} a possible (soft) duplicate: some other owner whose last-name
631	     * Soundex (see {@link SoundexResolver#soundex}) and postcode both match {@code owner}'s but whose derived
632	     * {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}) differs. An equal identity key would make
633	     * the two a hard duplicate, already rejected by {@link #requireUniqueIdentity}; a differing key with a matching
634	     * name-sound and postcode — for instance two owners sharing a last name and postcode but carrying different
635	     * telephones — is the soft match this flags. The postcode-present guard is applied by the caller (see
636	     * {@link #flagPossibleDuplicate}), so {@code owner}'s postcode is non-blank here.
637	     *
638	     * @param owner    the newly mapped owner about to be saved, with its normalized fields already in place
639	     * @param existing an already-persisted owner to test the new owner against
640	     * @return {@code true} when {@code existing} makes {@code owner} a possible duplicate
641	     */
642	    private boolean isPossibleDuplicateOf(Owner owner, Owner existing) {
643	        return SoundexResolver.soundex(owner.getLastName()).equals(SoundexResolver.soundex(existing.getLastName()))
644	            && owner.getPostcode().equals(existing.getPostcode())
645	            && !identityKeyResolver.deriveIdentityKey(owner).equals(identityKeyResolver.deriveIdentityKey(existing));
646	    }
