648	    /**
649	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
650	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
651	     *
652	     * @param city the city of the owner being created
653	     * @throws OwnerCityFullException if the city already contains 50 or more owners
654	     */
655	    private void requireCityHasCapacity(String city) {
656	        if (countOwnersInCity(city) >= MAX_OWNERS_PER_CITY) {
657	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
658	        }
659	    }
