661	    /**
662	     * Counts how many existing owners already belong to the given {@code city}, compared case-insensitively. Invoked
663	     * before the new owner is saved, so the count reflects only owners that predate this create; it never counts the
664	     * new owner itself. Factored out of {@link #requireCityHasCapacity} so the per-city owner count is expressed in one
665	     * place, mirroring how {@link #countOwnersRegisteredOn} backs the per-day rules.
666	     *
667	     * @param city the city to count owners for
668	     * @return the number of existing owners in that city
669	     */
670	    private long countOwnersInCity(String city) {
671	        return this.clinicService.findAllOwners().stream()
672	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
673	            .count();
674	    }
