676	    /**
677	     * Determines whether creating an owner in the given city should carry a capacity warning. The warning is raised
678	     * when the city (compared case-insensitively) already holds between {@value #CAPACITY_WARNING_THRESHOLD} and
679	     * {@code MAX_OWNERS_PER_CITY - 1} owners, i.e. it is approaching but has not yet reached the hard per-city limit of
680	     * {@value #MAX_OWNERS_PER_CITY}. Evaluated before the new owner is saved, so the count reflects only owners that
681	     * predate this create; the hard rejection at the limit (see {@link #requireCityHasCapacity}) still runs.
682	     *
683	     * @param city the city of the owner being created
684	     * @return {@code true} when the city already holds 40 to 49 owners, {@code false} otherwise
685	     */
686	    private boolean computeCapacityWarning(String city) {
687	        long count = countOwnersInCity(city);
688	        return count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY;
689	    }
