691	    /**
692	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
693	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
694	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
695	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
696	     * such owners never match one another as a household.
697	     *
698	     * @param owner the newly mapped owner about to be saved
699	     */
700	    private void assignHouseholdId(Owner owner) {
701	        String postcode = owner.getPostcode();
702	        if (postcode == null || postcode.isBlank()) {
703	            owner.setHouseholdId(null);
704	            return;
705	        }
706	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
707	    }
