709	    /**
710	     * Returns an owner's household-capped membership level: the level the {@link MembershipLevelResolver} derives from
711	     * the owner (see {@link MembershipLevelResolver#deriveMembershipLevel(Owner)}), lowered where necessary so it never
712	     * exceeds one above the highest capped level among the owner's <em>existing</em> household members — the members
713	     * that predate the owner, identified as those sharing its non-null {@code householdId} with a smaller id. When the
714	     * owner has no such existing household member (it is the first in its household, or has no household at all) no cap
715	     * applies and the derived level is returned unchanged. The owner's transient household member count is populated
716	     * first (see {@link #populateHouseholdMemberCount}) so the derived level reflects the current household size.
717	     *
718	     * @param owner the owner whose capped membership level should be computed
719	     * @return the membership level, capped at one above the existing household maximum
720	     */
721	    private int cappedMembershipLevel(Owner owner) {
722	        populateHouseholdMemberCount(owner);
723	        int level = MembershipLevelResolver.deriveMembershipLevel(owner);
724	        Integer cap = householdMembershipLevelCap(owner);
725	        return cap == null ? level : Math.min(level, cap);
726	    }
727	
728	    /**
729	     * Computes the ceiling the {@link #cappedMembershipLevel level-ceiling rule} imposes on a new owner: one above the
730	     * highest capped membership level among the owner's existing household members, or {@code null} when there is none.
731	     * An existing household member is an owner sharing this owner's non-null {@code householdId} whose id is smaller (so
732	     * it predates this owner); their levels are read with {@link #cappedMembershipLevel}, so each member's own ceiling
733	     * is respected in turn. An owner with no household ({@code null} householdId), no id yet, or no existing household
734	     * member has no cap.
735	     *
736	     * @param owner the owner whose household level cap should be computed
737	     * @return one above the existing household maximum level, or {@code null} when no cap applies
738	     */
739	    private Integer householdMembershipLevelCap(Owner owner) {
740	        String householdId = owner.getHouseholdId();
741	        Integer id = owner.getId();
742	        if (householdId == null || id == null) {
743	            return null;
744	        }
745	        Integer maxLevel = null;
746	        for (Owner member : this.clinicService.findAllOwners()) {
747	            Integer memberId = member.getId();
748	            if (memberId != null && memberId < id && householdId.equals(member.getHouseholdId())) {
749	                int memberLevel = cappedMembershipLevel(member);
750	                maxLevel = (maxLevel == null) ? memberLevel : Math.max(maxLevel, memberLevel);
751	            }
752	        }
753	        return maxLevel == null ? null : maxLevel + 1;
754	    }
755	
756	    /**
757	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
758	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
759	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
760	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
761	     * already been saved it is itself among the members returned.
762	     *
763	     * @param owner the owner whose household members should be resolved
764	     * @return the members of the owner's household, never empty
765	     */
766	    private List<Owner> householdMembers(Owner owner) {
767	        String householdId = owner.getHouseholdId();
768	        if (householdId == null) {
769	            return List.of(owner);
770	        }
771	        return this.clinicService.findAllOwners().stream()
772	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
773	            .toList();
774	    }
775	
776	    /**
777	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
778	     * household (see {@link #householdMembers}), i.e. those sharing the same non-null {@code householdId} (including the
779	     * owner itself). An owner with no household is counted as a household of one.
780	     *
781	     * @param owner the owner whose household size should be resolved
782	     */
783	    private void populateHouseholdMemberCount(Owner owner) {
784	        owner.setHouseholdMemberCount(householdMembers(owner).size());
785	    }
