788	    @Override
789	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
790	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
791	        if (currentOwner == null) {
792	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
793	        }
794	        validatePostcode(ownerFieldsDto);
795	        currentOwner.setAddress(ownerFieldsDto.getAddress());
796	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
797	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
798	        currentOwner.setCity(ownerFieldsDto.getCity());
799	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
800	        currentOwner.setLastName(ownerFieldsDto.getLastName());
801	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
802	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
803	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
804	        this.clinicService.saveOwner(currentOwner);
805	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
806	    }
807	
808	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
809	    @Transactional
810	    @Override
811	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
812	        Owner owner = this.clinicService.findOwnerById(ownerId);
813	        if (owner == null) {
814	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
815	        }
816	        owner.setDeleted(true);
817	        this.clinicService.saveOwner(owner);
818	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
819	    }
820	
821	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
822	    @Override
823	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
824	        Owner owner = this.clinicService.findOwnerById(ownerId);
825	        if (owner == null) {
826	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
827	        }
828	        HttpHeaders headers = new HttpHeaders();
829	        Pet pet = petMapper.toPet(petFieldsDto);
830	        owner.setId(ownerId);
831	        pet.setOwner(owner);
832	        pet.getType().setName(null);
833	        this.clinicService.savePet(pet);
834	        PetDto petDto = petMapper.toPetDto(pet);
835	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
836	            .buildAndExpand(pet.getId()).toUri());
837	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
838	    }
839	
840	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
841	    @Override
842	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
843	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
844	        if (currentOwner != null) {
845	            Pet currentPet = this.clinicService.findPetById(petId);
846	            if (currentPet != null) {
847	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
848	                currentPet.setName(petFieldsDto.getName());
849	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
850	                this.clinicService.savePet(currentPet);
851	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
852	            }
853	        }
854	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
855	    }
856	
857	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
858	    @Override
859	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
860	        HttpHeaders headers = new HttpHeaders();
861	        Visit visit = visitMapper.toVisit(visitFieldsDto);
862	        Pet pet = new Pet();
863	        pet.setId(petId);
864	        visit.setPet(pet);
865	        this.clinicService.saveVisit(visit);
866	        VisitDto visitDto = visitMapper.toVisitDto(visit);
867	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
868	            .buildAndExpand(visit.getId()).toUri());
869	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
870	    }
871	
872	
873	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
874	    @Override
875	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
876	        Owner owner = this.clinicService.findOwnerById(ownerId);
877	        if (owner != null) {
878	            Pet pet = owner.getPet(petId);
879	            if (pet != null) {
